def render_tree(paths):
    """Return tree lines for archive member paths, preserving encounter order.

    Directory paths may be explicit (with a trailing slash) or inferred from
    descendants. Repeated directory entries are displayed only once.
    """
    root = {"children": {}, "kind": "dir"}
    for raw in paths:
        path = str(raw).replace("\\", "/").strip("/")
        if not path or path == ".":
            continue
        parts = [p for p in path.split("/") if p and p != "."]
        node = root
        for i, part in enumerate(parts):
            final = i == len(parts) - 1
            is_dir = not final or str(raw).endswith("/")
            children = node["children"]
            if part not in children:
                children[part] = {"children": {}, "kind": "dir" if is_dir else "file"}
            child = children[part]
            if is_dir:
                child["kind"] = "dir"
            node = child

    lines = []

    def walk(node, prefix=""):
        entries = list(node["children"].items())
        for idx, (name, child) in enumerate(entries):
            last = idx == len(entries) - 1
            branch = "└── " if last else "├── "
            directory = child["kind"] == "dir"
            lines.append(prefix + branch + name + ("/" if directory else ""))
            if directory and child["children"]:
                walk(child, prefix + ("   " if last else "│  "))

    walk(root)
    return lines
